                                                                            <td><?= $val ?></td>
                                                                        <?php endforeach; ?>
                                                                        <th>
                                                                                <center><b>
                                                                                <?php
                                                                                // Koneksi database
                                                                                error_reporting(0);
                                                                                ini_set('display_errors', 0);


                                                                            

                                                                                // Ambil data tingkat_risiko dalam rentang waktu
                                                                                $query = "
                                                                                    SELECT (tahun * 10 + periode) AS key_form, inheren_kredit
                                                                                    FROM frame_laporan_profil_risiko 
                                                                                    INNER JOIN keterangan_profil_kredit 
                                                                                        ON frame_laporan_profil_risiko.id_profil_risiko = keterangan_profil_kredit.id_profil_risiko
                                                                                    WHERE (tahun * 10 + periode) BETWEEN $start_key AND $end_key 
                                                                                        AND kantor_cabang = $kode_kantor_tren AND user = $user
                                                                                    ORDER BY tahun ASC, periode ASC
                                                                                ";

                                                                                $result = mysqli_query($conn, $query);

                                                                                $x = [];
                                                                                $y = [];
                                                                                $i = 0;

                                                                                while ($row = mysqli_fetch_assoc($result)) {
                                                                                    if (is_numeric($row['inheren_kredit'])) {
                                                                                        $x[] = $i++; // Gunakan indeks sebagai variabel waktu (bisa diganti key_form)
                                                                                        $y[] = floatval($row['inheren_kredit']);
                                                                                    }
                                                                                }

                                                                                // Cek jumlah data
                                                                                $n = count($x);
                                                                                if ($n < 2) {
                                                                                    $peringatan = "Data tidak cukup untuk analisis tren atau pilih range periode lagi.";
                                                                                }
                                                                                else {
                                                                                    $peringatan = " ";
                                                                                }

                                                                                // Hitung regresi linier (y = a + b*x)
                                                                                $sumX = array_sum($x);
                                                                                $sumY = array_sum($y);
                                                                                $sumXY = 0;
                                                                                $sumX2 = 0;

                                                                                for ($i = 0; $i < $n; $i++) {
                                                                                    $sumXY += $x[$i] * $y[$i];
                                                                                    $sumX2 += $x[$i] * $x[$i];
                                                                                }

                                                                                if ($n >= 2 && ($n * $sumX2 - $sumX * $sumX) != 0) {
                                                                                $tren = 'Stay';
                                                                                $b = ($n * $sumXY - $sumX * $sumY) / ($n * $sumX2 - $sumX * $sumX); // slope
