                                                                        <th>Risiko Inheren</th>
                                                                        <?php foreach ($inheren_stra as $val): ?>
                                                                            <td><?= $val ?></td>
                                                                        <?php endforeach; ?>
                                                                        <th>
                                                                                <center><b> <?php
                                                                                // Koneksi database



                                                                            

                                                                                // Ambil data tingkat_risiko dalam rentang waktu
                                                                                $query = "
                                                                                    SELECT (tahun * 10 + periode) AS key_form, inheren_stratejik
                                                                                    FROM frame_laporan_profil_risiko 
                                                                                    INNER JOIN keterangan_profil_stratejik 
                                                                                        ON frame_laporan_profil_risiko.id_profil_risiko = keterangan_profil_stratejik.id_profil_risiko
                                                                                    WHERE (tahun * 10 + periode) BETWEEN $start_key AND $end_key 
                                                                                        AND kantor_cabang = $kode_kantor_tren AND user = $user
                                                                                    ORDER BY tahun ASC, periode ASC
                                                                                ";

                                                                                $result = mysqli_query($conn, $query);

                                                                                $x = [];
                                                                                $y = [];
                                                                                $i = 0;

                                                                                while ($row = mysqli_fetch_assoc($result)) {
                                                                                    if (is_numeric($row['inheren_stratejik'])) {
                                                                                        $x[] = $i++; // Gunakan indeks sebagai variabel waktu (bisa diganti key_form)
                                                                                        $y[] = floatval($row['inheren_stratejik']);
                                                                                    }
                                                                                }

                                                                                // Cek jumlah data
                                                                                $n = count($x);
                                                                                if ($n < 2) {
                                                                                    $peringatan = "Data tidak cukup untuk analisis tren atau pilih range periode lagi.";
                                                                                }
                                                                                else {
                                                                                    $peringatan = " ";
                                                                                }

                                                                                // Hitung regresi linier (y = a + b*x)
                                                                                $sumX = array_sum($x);
                                                                                $sumY = array_sum($y);
                                                                                $sumXY = 0;
                                                                                $sumX2 = 0;

                                                                                for ($i = 0; $i < $n; $i++) {
                                                                                    $sumXY += $x[$i] * $y[$i];
                                                                                    $sumX2 += $x[$i] * $x[$i];
                                                                                }

                                                                                if ($n >= 2 && ($n * $sumX2 - $sumX * $sumX) != 0) {
                                                                                $tren = 'Stay';
                                                                                $b = ($n * $sumXY - $sumX * $sumY) / ($n * $sumX2 - $sumX * $sumX); // slope
                                                                                $a = ($sumY - $b * $sumX) / $n; // intercept

                                                                                // Tentukan tren
                                                                                if ($b > 0.01) {
                                                                                    $tren = "Memburuk";
                                                                                } elseif ($b < -0.01) {
                                                                                    $tren = "Membaik";
                                                                                } elseif($b == 0) {
                                                                                    $tren = "Stay";
                                                                                }
                        
                                                                                if ($tren == "Membaik") {
                                                                                    echo '<span class="badge badge-success-lighten rounded-pill">Tren Membaik</span> <i class="mdi mdi-arrow-down text-success"></i><br>' . $b . '';
                                                                                } else if ($tren == "Memburuk") {
                                                                                    echo '<span class="badge badge-danger-lighten rounded-pill">Tren Memburuk</span> <i class="mdi mdi-arrow-up text-danger"></i><br>' . $b . '';
                                                                                } else if ($tren == "Stay") {
                                                                                    echo '<span class="badge badge-warning-lighten rounded-pill">Tren Statis</span> <i class="mdi mdi-arrow-right text-warning"></i><br>' . $b . '';
                                                                                } else {
                                                                                    echo '<span>-</span> </i>';
                                                                                }
                                                                                
                                                                                

                                                                                } else {
                                                                                    echo '<span>-</span>';
                                                                                }
?></b></center>
